import Phaser from 'phaser'
import { aiDriversOf, buildRacingLine, type CarSnapshot, type RacingLine, type Session, type TrackRuntime } from '@sim'
import type { WorldView } from '../config'
import { DEPTH } from '../race/depth'

// Palette colours (spec/00-product/art-direction.md), one per line so that the lines of different drivers can be told apart.
const LINES = [0xfbdc4a, 0x9ad4ff, 0xfa90be, 0x5cc85a, 0xff7a1c, 0xeef1f6, 0xff9a78]
/** Where a wheel of a car on the line is on a kerb. */
const ON_KERB = 0xf0181e
const AIM = 0xffffff
const RECOVERING = 0xf0181e

/** Drawn above everything in the race but the HUD, beside the wall overlay. */
const OVERLAY_DEPTH = DEPTH.hud - 4
/** A line is drawn through every so many of its points: a quarter of a metre a stroke, which no bend of the track shows as a corner. */
const POINTS_PER_STROKE = 3
/** Half the size of the cross drawn on the point a driver is aiming at, screen pixels. */
const CROSS_PX = 5
/** The name of the overlay's graphics objects. It is also how the production scan knows the overlay when it sees it. */
export const RACING_LINE_OVERLAY_NAME = 'mrr-racing-line-overlay'

/**
 * A development overlay (F-301): the racing line of every AI driver in the session, and the point each is steering
 * for, with a stroke from its car to that point. A line is drawn once; the aim points are redrawn each frame while
 * the overlay shows. In a session with no AI cars it draws the line a careful driver of perfect skill would take.
 * Hidden until `toggle()`; the race scene binds the L key to it, and shows `L LINES` among the key hints, once the
 * tuning tools are unlocked (at start in development, test and demo builds; in the released game when the code is typed, F-813).
 * Its code is a chunk of its own that production does not fetch before then. It reads the drivers and the snapshots and
 * changes nothing.
 */
export class RacingLineOverlay {
  private readonly lines: Phaser.GameObjects.Graphics
  private readonly aims: Phaser.GameObjects.Graphics
  /** How many different lines were drawn. */
  readonly lineCount: number

  constructor(
    scene: Phaser.Scene,
    private readonly session: Session,
    runtime: TrackRuntime,
    carWidthM: number,
    private readonly view: WorldView,
  ) {
    this.lines = scene.add.graphics().setDepth(OVERLAY_DEPTH).setVisible(false).setName(RACING_LINE_OVERLAY_NAME)
    this.aims = scene.add.graphics().setDepth(OVERLAY_DEPTH).setVisible(false).setName(RACING_LINE_OVERLAY_NAME)
    // Drivers of the same skill and temperament share a line: each is drawn once.
    const drawn = new Set<RacingLine>()
    for (const driver of aiDriversOf(session)) if (driver !== null) drawn.add(driver.line)
    if (drawn.size === 0) drawn.add(buildRacingLine(runtime, carWidthM))
    let index = 0
    for (const line of drawn) this.draw(line, LINES[index++ % LINES.length])
    this.lineCount = drawn.size
  }

  get visible(): boolean {
    return this.lines.visible
  }

  /** Flips the overlay and returns whether it is now showing. */
  toggle(): boolean {
    const showing = !this.lines.visible
    this.lines.setVisible(showing)
    this.aims.setVisible(showing)
    if (!showing) this.aims.clear()
    return showing
  }

  /** Redraws where each AI driver is aiming, from the cars as they are being shown. Does nothing while hidden. */
  update(cars: readonly Pick<CarSnapshot, 'id' | 'pose'>[]): void {
    if (!this.lines.visible) return
    const g = this.aims
    g.clear()
    aiDriversOf(this.session).forEach((driver, id) => {
      const car = cars[id]
      if (driver === null || car === undefined) return
      const [carX, carY] = this.px(car.pose.x, car.pose.y)
      const [aimX, aimY] = this.px(driver.target.x, driver.target.y)
      g.lineStyle(1, driver.recovering ? RECOVERING : AIM, 1)
      g.lineBetween(carX, carY, aimX, aimY)
      g.lineBetween(aimX - CROSS_PX, aimY, aimX + CROSS_PX, aimY)
      g.lineBetween(aimX, aimY - CROSS_PX, aimX, aimY + CROSS_PX)
    })
  }

  destroy(): void {
    this.lines.destroy()
    this.aims.destroy()
  }

  private px(x: number, y: number): [number, number] {
    return [this.view.originX + x * this.view.pxPerM, this.view.originY + y * this.view.pxPerM]
  }

  private draw(line: RacingLine, colour: number): void {
    const g = this.lines
    const count = line.points.length
    for (let i = 0; i < count; i += POINTS_PER_STROKE) {
      const from = line.points[i]
      const to = line.points[(i + POINTS_PER_STROKE) % count]
      const [x0, y0] = this.px(from.x, from.y)
      const [x1, y1] = this.px(to.x, to.y)
      g.lineStyle(1, from.onKerb ? ON_KERB : colour, 1)
      g.lineBetween(x0, y0, x1, y1)
    }
  }
}
